    // Probability that a human dies from disease.
    private static final double HUMAN_DEATH_FROM_DISEASE_PROBABILITY = 0.05;
    // List of all human prey.
    private final ArrayList<Class> LIST_OF_PREY = new ArrayList<>() {
            {
                add(Dodo.class);
                add(Pig.class);
            }
        };

